  "description": "Search the web and return a ranked list of results with title, url, and snippet",
  "inputSchema": {
    "type": "object",
    "properties": {
      "query": { "type": "string" },
      "max_results": { "type": "integer", "minimum": 1, "maximum": 10, "default": 5 },
      "recency": { "type": "string", "enum": ["any", "day", "week", "month", "year"], "default": "any" }
    },
    "required": ["query"]
  }
}

async function handleSearch({ query, max_results = 5, recency = "any" }) {
  const resp = await fetch("https://search-provider.example.com/v1/search", {
    method: "POST",
    headers: { "Authorization": `Bearer ${process.env.SEARCH_API_KEY}`, "Content-Type": "application/json" },
    body: JSON.stringify({ q: query, limit: max_results, freshness: recency })
  });
  const data = await resp.json();
  const results = data.items.slice(0, max_results).map((item, i) => ({
    rank: i + 1,
    title: item.title,
    url: item.url,
    snippet: item.snippet
  }));
  return { query, results };
}

async function handleFetchPage({ url }) {
  const resp = await fetch(url, { redirect: "follow", signal: AbortSignal.timeout(8000) });
  if (!resp.ok) {
    return { url, error: `fetch failed with status ${resp.status}` };
  }
  const html = await resp.text();
  const text = extractReadableText(html);
  return {
    url,
    title: extractTitle(html),
    content: text.slice(0, 20000)
  };
}

const cache = new Map();

async function cachedSearch(query, maxResults) {
  const key = `${query}::${maxResults}`;
  const hit = cache.get(key);
  if (hit && Date.now() - hit.ts < 10 * 60 * 1000) {
    return hit.value;
  }
  const value = await handleSearch({ query, max_results: maxResults });
  cache.set(key, { value, ts: Date.now() });
  return value;
}

